sparql:
SELECT ?key ?name WHERE {
  ?x a proto:Codebase .
  OPTIONAL { ?x proto:name ?name }
  BIND(STR(?x) AS ?key)
}
ORDER BY ?name
LIMIT 25

SELECT ?id ?path WHERE {
  ?x a proto:SourceFile .
  BIND(STR(?x) AS ?id)
  OPTIONAL { ?x proto:path ?path }
}
ORDER BY ?id
LIMIT 25

SELECT (COUNT(?x) AS ?count) WHERE {
  ?x a proto:SourceFile ;
     proto:partOf "pb-kane" .
}

SELECT ?key ?name WHERE {
  ?x a proto:SourceFile .
  OPTIONAL { ?x proto:name ?name }
  BIND(STR(?x) AS ?key)
}
ORDER BY ?name
LIMIT 25
